                            node = new HashEntry<K,V>(hash, key, value, first);
                        int c = count + 1;
                        // 查看是否需要更新HashEntry
                        if (c > threshold && tab.length < MAXIMUM_CAPACITY)
                            rehash(node);
                        else
                            // 重置HashEntry的位置
                            setEntryAt(tab, index, node);
                        ++modCount;
                        count = c;
                        oldValue = null;
