           --pool->ref.count;
           size = pool->szidx;
           next = usedpools[size + size];
           prev = next->prevpool;
           /* insert pool before next:   prev <-> pool <-> next */
           pool->nextpool = next;
           pool->prevpool = prev;
           next->prevpool = pool;
           prev->nextpool = pool;
           return;
       }
       ……
   }
